head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        footerExist: "0"
    }
    grd.advancedExcelUpload(options);
};
scwin.trigger2_onclick = function(e) {
    var options = {
        fileName: 'test.xlsx',
        useStyle: 'true',
        footerFontName: '맑은 고딕'
    };
    grd.advancedExcelDownload(options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_3_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_3_calendar_picker_header_dynamic_entity').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_3_calendar_picker_cell_0').innerText == '1월'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('w2calendar_go_today')[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('wq_uuid_3_calendar_content').style.display == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
}
